{# GoFix Service Invoice - compact GST invoice for Sales Invoice #}
{%- set sr_name = doc.custom_gofix_service_request or frappe.db.get_value("Service Request", {"service_invoice": doc.name}, "name") -%}
{%- set sr = frappe.get_doc("Service Request", sr_name) if sr_name else None -%}
{%- set company = frappe.get_cached_doc("Company", doc.company) -%}
{%- set currency = doc.currency or company.default_currency or "INR" -%}

{%- set company_addr_name = doc.company_address or frappe.db.get_value("Dynamic Link", {"link_doctype": "Company", "link_name": doc.company, "parenttype": "Address"}, "parent") -%}
{%- set company_addr = frappe.db.get_value("Address", company_addr_name, ["address_line1", "address_line2", "city", "state", "pincode", "country", "gstin", "phone", "email_id"], as_dict=True) if company_addr_name else None -%}
{%- set company_gstin = doc.company_gstin or company.get("gstin") or (company_addr.gstin if company_addr else "") -%}
{%- set company_pan = company.tax_id or "" -%}

{%- set customer_info = frappe.db.get_value("Customer", doc.customer, ["mobile_no", "email_id", "customer_primary_address", "gstin"], as_dict=True) if doc.customer else None -%}
{%- set customer_addr_name = doc.customer_address or (customer_info.customer_primary_address if customer_info else None) -%}
{%- set customer_addr = frappe.db.get_value("Address", customer_addr_name, ["address_line1", "address_line2", "city", "state", "pincode", "country", "gstin", "phone", "email_id"], as_dict=True) if customer_addr_name else None -%}
{%- set customer_gstin = doc.billing_address_gstin or (customer_info.gstin if customer_info else "") or (customer_addr.gstin if customer_addr else "") -%}
{%- set customer_phone = doc.contact_mobile or doc.contact_phone or (sr.contact_number if sr else "") or (customer_info.mobile_no if customer_info else "") -%}
{%- set customer_email = doc.contact_email or (customer_info.email_id if customer_info else "") -%}
{%- set place_of_supply = doc.place_of_supply or ((sr.state_code ~ " - " ~ sr.state_name) if sr and sr.state_code and sr.state_name else (sr.state_name if sr else "")) -%}

{%- set totals = namespace(taxable=0, cgst=0, sgst=0, igst=0, qty=0) -%}
{%- for item in doc.items -%}
	{%- set line_taxable = item.taxable_value if item.taxable_value else (item.net_amount or item.amount or 0) -%}
	{%- set totals.taxable = totals.taxable + (line_taxable or 0) -%}
	{%- set totals.cgst = totals.cgst + (item.cgst_amount or 0) -%}
	{%- set totals.sgst = totals.sgst + (item.sgst_amount or 0) -%}
	{%- set totals.igst = totals.igst + (item.igst_amount or 0) -%}
	{%- set totals.qty = totals.qty + (item.qty or 0) -%}
{%- endfor -%}

{% macro money(value) -%}
{{ frappe.utils.fmt_money(value or 0, currency=currency) }}
{%- endmacro %}

{% macro address_block(addr) -%}
	{%- if addr -%}
		{{ addr.address_line1 or "" }}{% if addr.address_line2 %}<br>{{ addr.address_line2 }}{% endif %}
		{% if addr.city or addr.state or addr.pincode %}<br>{{ [addr.city, addr.state, addr.pincode] | select | join(", ") }}{% endif %}
		{% if addr.country %}<br>{{ addr.country }}{% endif %}
		{% if addr.phone %}<br>Phone: {{ addr.phone }}{% endif %}
		{% if addr.email_id %}<br>Email: {{ addr.email_id }}{% endif %}
	{%- else -%}
		<span class="muted">Not configured</span>
	{%- endif -%}
{%- endmacro %}

<style>
	.gfix-inv {
		color: #111827;
		font-family: Arial, Helvetica, sans-serif;
		font-size: 10px;
		line-height: 1.35;
	}
	.gfix-inv * { box-sizing: border-box; }
	.gfix-inv .top {
		background: #14365d;
		color: #fff;
		display: table;
		margin-bottom: 0;
		padding: 9px 12px;
		width: 100%;
	}
	.gfix-inv .title {
		display: table-cell;
		font-size: 17px;
		font-weight: 800;
		letter-spacing: 2px;
		text-transform: uppercase;
		vertical-align: middle;
	}
	.gfix-inv .copy {
		display: table-cell;
		font-size: 9px;
		font-style: italic;
		text-align: right;
		vertical-align: middle;
	}
	.gfix-inv .box {
		border: 1px solid #cbd5e1;
		border-top: 0;
		padding: 10px 12px;
	}
	.gfix-inv .grid {
		display: grid;
		grid-template-columns: 1.15fr 0.85fr;
	}
	.gfix-inv .brand-name {
		color: #14365d;
		font-size: 18px;
		font-weight: 800;
		margin-bottom: 5px;
		text-transform: uppercase;
	}
	.gfix-inv .meta {
		background: #eef4fb;
		border-left: 3px solid #14365d;
		padding: 8px 10px;
	}
	.gfix-inv .meta-row {
		display: grid;
		grid-template-columns: 110px 1fr;
		margin-bottom: 5px;
	}
	.gfix-inv .label {
		color: #475569;
		font-size: 8.5px;
		font-weight: 800;
		text-transform: uppercase;
	}
	.gfix-inv .value { font-weight: 700; }
	.gfix-inv .muted { color: #6b7280; }
	.gfix-inv .danger { color: #b91c1c; font-weight: 700; }
	.gfix-inv .section-title {
		background: #f3f4f6;
		border: 1px solid #cbd5e1;
		border-top: 0;
		color: #111827;
		font-size: 9px;
		font-weight: 800;
		padding: 5px 8px;
		text-transform: uppercase;
	}
	.gfix-inv .party-grid {
		border-left: 1px solid #cbd5e1;
		border-right: 1px solid #cbd5e1;
		display: grid;
		grid-template-columns: 1fr 1fr;
	}
	.gfix-inv .party {
		border-right: 1px solid #cbd5e1;
		min-height: 80px;
		padding: 9px 12px;
	}
	.gfix-inv .party:last-child { border-right: 0; }
	.gfix-inv .party-head {
		background: #14365d;
		border-radius: 2px;
		color: #fff;
		display: inline-block;
		font-size: 8.5px;
		font-weight: 800;
		margin-bottom: 5px;
		padding: 2px 7px;
		text-transform: uppercase;
	}
	.gfix-inv .service-strip {
		background: #f8fafc;
		border: 1px solid #cbd5e1;
		border-top: 0;
		padding: 8px 12px;
	}
	.gfix-inv .pill {
		background: #e0f2fe;
		border: 1px solid #bae6fd;
		border-radius: 3px;
		color: #075985;
		display: inline-block;
		font-size: 8.5px;
		font-weight: 700;
		margin: 2px 4px 2px 0;
		padding: 2px 6px;
	}
	.gfix-inv table {
		border-collapse: collapse;
		width: 100%;
	}
	.gfix-inv th {
		background: #14365d;
		border: 1px solid #14365d;
		color: #fff;
		font-size: 8.5px;
		font-weight: 800;
		padding: 6px 5px;
		text-align: left;
		text-transform: uppercase;
	}
	.gfix-inv td {
		border: 1px solid #dbe3ee;
		padding: 6px 5px;
		vertical-align: top;
	}
	.gfix-inv .right { text-align: right; }
	.gfix-inv .center { text-align: center; }
	.gfix-inv .nowrap { white-space: nowrap; }
	.gfix-inv .summary-wrap {
		display: grid;
		gap: 10px;
		grid-template-columns: 1fr 260px;
		margin-top: 10px;
	}
	.gfix-inv .terms {
		border: 1px solid #cbd5e1;
		padding: 9px 10px;
	}
	.gfix-inv .summary td { padding: 5px 7px; }
	.gfix-inv .summary .grand td {
		background: #14365d;
		color: #fff;
		font-size: 12px;
		font-weight: 800;
	}
	.gfix-inv .footer {
		align-items: end;
		display: grid;
		gap: 10px;
		grid-template-columns: 1fr 210px;
		margin-top: 12px;
	}
	.gfix-inv .sign {
		border: 1px solid #cbd5e1;
		min-height: 68px;
		padding: 8px;
		text-align: center;
	}
	.gfix-inv .sign-line {
		border-top: 1px solid #111827;
		margin-top: 34px;
		padding-top: 4px;
	}
	@media print {
		.gfix-inv .top,
		.gfix-inv th,
		.gfix-inv .summary .grand td,
		.gfix-inv .party-head {
			-webkit-print-color-adjust: exact;
			print-color-adjust: exact;
		}
	}
</style>

<div class="gfix-inv">
	<div class="top">
		<div class="title">Tax Invoice</div>
		<div class="copy">Original for Recipient</div>
	</div>

	<div class="box grid">
		<div>
			<div class="brand-name">{{ company.company_name or doc.company }}</div>
			<div>
				{% if doc.company_address_display %}
					{{ doc.company_address_display | safe }}
				{% else %}
					{{ address_block(company_addr) }}
				{% endif %}
			</div>
			<div style="margin-top:5px;">
				<span class="label">GSTIN:</span>
				{% if company_gstin %}<span class="value">{{ company_gstin }}</span>{% else %}<span class="danger">Not configured</span>{% endif %}
				{% if company_pan %} &nbsp; <span class="label">PAN:</span> <span class="value">{{ company_pan }}</span>{% endif %}
			</div>
		</div>
		<div class="meta">
			<div class="meta-row"><span class="label">Invoice No</span><span class="value">{{ doc.name }}</span></div>
			<div class="meta-row"><span class="label">Invoice Date</span><span class="value">{{ frappe.utils.format_date(doc.posting_date) }}{% if doc.posting_time %} {{ frappe.utils.format_time(doc.posting_time) }}{% endif %}</span></div>
			<div class="meta-row"><span class="label">Place of Supply</span><span class="value">{{ place_of_supply or "-" }}</span></div>
			<div class="meta-row"><span class="label">Reverse Charge</span><span class="value">{{ "Yes" if doc.get("is_reverse_charge") else "No" }}</span></div>
			<div class="meta-row"><span class="label">Status</span><span class="value">{{ doc.status }}</span></div>
		</div>
	</div>

	<div class="section-title">Customer and Service Centre</div>
	<div class="party-grid">
		<div class="party">
			<div class="party-head">Bill To</div>
			<div class="value">{{ doc.customer_name or doc.customer }}</div>
			{% if customer_phone %}<div>Mobile: {{ customer_phone }}</div>{% endif %}
			{% if customer_email %}<div>Email: {{ customer_email }}</div>{% endif %}
			<div style="margin-top:5px;">
				{% if doc.address_display %}
					{{ doc.address_display | safe }}
				{% elif sr and sr.billing_address_display %}
					{{ sr.billing_address_display | safe }}
				{% else %}
					{{ address_block(customer_addr) }}
				{% endif %}
			</div>
			<div style="margin-top:4px;"><span class="label">Customer GSTIN:</span> {{ customer_gstin or "Unregistered / Not provided" }}</div>
		</div>
		<div class="party">
			<div class="party-head">Service Centre</div>
			<div><span class="label">POS Profile:</span> <span class="value">{{ doc.pos_profile or "-" }}</span></div>
			<div><span class="label">Warehouse:</span> <span class="value">{{ doc.set_warehouse or (sr.source_warehouse if sr else "") or "-" }}</span></div>
			{% if sr and sr.transferred_to_store %}
				<div><span class="label">Repair Hub:</span> <span class="value">{{ sr.transferred_to_store }}</span></div>
			{% endif %}
			{% if doc.owner %}
				<div><span class="label">Billed By:</span> {{ frappe.db.get_value("User", doc.owner, "full_name") or doc.owner }}</div>
			{% endif %}
		</div>
	</div>

	{% if sr %}
	<div class="service-strip">
		<span class="pill">SR: {{ sr.name }}</span>
		{% if sr.service_order %}<span class="pill">SO: {{ sr.service_order }}</span>{% endif %}
		{% if sr.device_item_name or sr.device_item %}<b>Device:</b> {{ sr.device_item_name or sr.device_item }}{% endif %}
		{% if sr.brand %} &nbsp; <b>Brand:</b> {{ sr.brand }}{% endif %}
		{% if sr.serial_no or sr.actual_imei %} &nbsp; <b>Serial / IMEI:</b> {{ sr.serial_no or sr.actual_imei }}{% endif %}
		{% if sr.issue_category %}<br><b>Issue:</b> {{ sr.issue_category }}{% if sr.issue_description %} - {{ sr.issue_description | striptags | truncate(150) }}{% endif %}{% endif %}
		{% if sr.accessories_received %}<br><b>Accessories:</b> {{ sr.accessories_received }}{% endif %}
	</div>
	{% endif %}

	<table>
		<thead>
			<tr>
				<th style="width:28px;">#</th>
				<th>Description</th>
				<th style="width:70px;">HSN/SAC</th>
				<th class="right" style="width:45px;">Qty</th>
				<th class="right" style="width:75px;">Rate</th>
				<th class="right" style="width:80px;">Taxable</th>
				<th class="right" style="width:58px;">CGST</th>
				<th class="right" style="width:58px;">SGST</th>
				<th class="right" style="width:58px;">IGST</th>
				<th class="right" style="width:80px;">Total</th>
			</tr>
		</thead>
		<tbody>
			{% for item in doc.items %}
				{% set line_taxable = item.taxable_value if item.taxable_value else (item.net_amount or item.amount or 0) %}
				{% set line_tax = (item.cgst_amount or 0) + (item.sgst_amount or 0) + (item.igst_amount or 0) %}
				<tr>
					<td class="center">{{ loop.index }}</td>
					<td>
						<div class="value">{{ item.item_name or item.item_code }}</div>
						{% if item.description and item.description != item.item_name %}
							<div class="muted">{{ item.description | striptags }}</div>
						{% endif %}
						{% if item.serial_no %}<div class="muted">Serial: {{ item.serial_no | replace("\n", ", ") }}</div>{% endif %}
						{% if item.gst_treatment %}<div class="muted">GST Treatment: {{ item.gst_treatment }}</div>{% endif %}
					</td>
					<td>{{ item.gst_hsn_code or "-" }}</td>
					<td class="right">{{ "%g"|format(item.qty or 0) }}</td>
					<td class="right nowrap">{{ money(item.rate) }}</td>
					<td class="right nowrap">{{ money(line_taxable) }}</td>
					<td class="right nowrap">{{ "%g"|format(item.cgst_rate or 0) }}%<br>{{ money(item.cgst_amount) }}</td>
					<td class="right nowrap">{{ "%g"|format(item.sgst_rate or 0) }}%<br>{{ money(item.sgst_amount) }}</td>
					<td class="right nowrap">{{ "%g"|format(item.igst_rate or 0) }}%<br>{{ money(item.igst_amount) }}</td>
					<td class="right nowrap">{{ money(line_taxable + line_tax) }}</td>
				</tr>
			{% endfor %}
		</tbody>
	</table>

	<div class="summary-wrap">
		<div class="terms">
			<div class="label">Payment</div>
			{% if doc.payments %}
				{% for p in doc.payments %}
					<div>{{ p.mode_of_payment }} - <b>{{ money(p.amount) }}</b></div>
				{% endfor %}
			{% else %}
				<div class="muted">No payment rows found</div>
			{% endif %}
			<div style="margin-top:8px;"><span class="label">Amount in Words</span>{{ doc.in_words or frappe.utils.money_in_words(doc.grand_total or 0, currency) }}</div>
			<div style="margin-top:8px;">
				<span class="label">Service Terms</span>
				Warranty applies only to the repair/service performed. Data backup is customer responsibility. Original invoice is required for warranty support.
			</div>
			{% if sr and sr.repair_warranty_days %}
				<div style="margin-top:6px;"><b>Repair Warranty:</b> {{ sr.repair_warranty_days }} days{% if sr.repair_warranty_expiry %}, valid till {{ frappe.utils.format_date(sr.repair_warranty_expiry) }}{% endif %}</div>
			{% endif %}
		</div>
		<table class="summary">
			<tr><td>Total Qty</td><td class="right">{{ "%g"|format(totals.qty) }}</td></tr>
			<tr><td>Taxable / Exempt Value</td><td class="right nowrap">{{ money(totals.taxable) }}</td></tr>
			<tr><td>CGST</td><td class="right nowrap">{{ money(totals.cgst) }}</td></tr>
			<tr><td>SGST</td><td class="right nowrap">{{ money(totals.sgst) }}</td></tr>
			<tr><td>IGST</td><td class="right nowrap">{{ money(totals.igst) }}</td></tr>
			{% if doc.discount_amount %}<tr><td>Discount</td><td class="right nowrap">- {{ money(doc.discount_amount) }}</td></tr>{% endif %}
			{% if doc.rounding_adjustment %}<tr><td>Round Off</td><td class="right nowrap">{{ money(doc.rounding_adjustment) }}</td></tr>{% endif %}
			<tr class="grand"><td>Grand Total</td><td class="right nowrap">{{ money(doc.rounded_total or doc.grand_total) }}</td></tr>
			<tr><td>Paid</td><td class="right nowrap">{{ money(doc.paid_amount) }}</td></tr>
			<tr><td>Outstanding</td><td class="right nowrap">{{ money(doc.outstanding_amount) }}</td></tr>
		</table>
	</div>

	<div class="footer">
		<div class="muted">
			Generated {{ frappe.utils.format_datetime(frappe.utils.now_datetime(), "dd MMM yyyy HH:mm") }}.
			{% if not company_gstin %}<br><span class="danger">Company GSTIN is not configured.</span>{% endif %}
			{% if not doc.address_display and not customer_addr and not (sr and sr.billing_address_display) %}<br><span class="danger">Customer billing address is not configured.</span>{% endif %}
		</div>
		<div class="sign">
			<div class="value">For {{ company.company_name or doc.company }}</div>
			<div class="sign-line">Authorised Signatory</div>
		</div>
	</div>
</div>
